class SegmentTree {
    vector<long long> tree, lazy;
    int n;

    void push(int v, int tl, int tr) {
        if (lazy[v] != 0 && tl != tr) {
            lazy[2*v] += lazy[v];
            lazy[2*v+1] += lazy[v];
            tree[2*v] += lazy[v];
            tree[2*v+1] += lazy[v];
        }
        lazy[v] = 0;
    }

    void update(int v, int tl, int tr, int l, int r, long long val) {
        if (l > r) return;
        if (l == tl && r == tr) {
            tree[v] += val;
            lazy[v] += val;
            return;
        }
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        update(2*v, tl, tm, l, min(r, tm), val);
        update(2*v+1, tm+1, tr, max(l, tm+1), r, val);
        tree[v] = min(tree[2*v] + lazy[2*v], tree[2*v+1] + lazy[2*v+1]);
    }

    long long query(int v, int tl, int tr, int l, int r) {
        if (l > r) return LLONG_MAX;
        if (l == tl && r == tr) {
            return tree[v];
        }
        push(v, tl, tr);
        int tm = (tl + tr) / 2;
        return min(query(2*v, tl, tm, l, min(r, tm)),
                   query(2*v+1, tm+1, tr, max(l, tm+1), r));
    }

public:
    SegmentTree(vector<long long>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        lazy.resize(4 * n);
        build(arr, 1, 0, n-1);
    }

    void build(vector<long long>& arr, int v, int tl, int tr) {
        if (tl == tr) {
            tree[v] = arr[tl];
        } else {
            int tm = (tl + tr) / 2;
